mapper.update:
UPDATE oa_budget_line
SET reserved_amount = IFNULL(reserved_amount, 0) + #{amount},
    available_amount = IFNULL(available_amount, 0) - #{amount}
WHERE line_id = #{lineId}
  AND IFNULL(available_amount, 0) >= #{amount}

UPDATE oa_budget_line
SET available_amount = IFNULL(available_amount, 0) + LEAST(IFNULL(reserved_amount, 0), #{amount}) - #{amount},
    actual_amount = IFNULL(actual_amount, 0) + #{amount},
    reserved_amount = IFNULL(reserved_amount, 0) - LEAST(IFNULL(reserved_amount, 0), #{amount})
WHERE line_id = #{lineId}
  AND IFNULL(available_amount, 0) + LEAST(IFNULL(reserved_amount, 0), #{amount}) >= #{amount}

UPDATE oa_budget_line
SET amount = IFNULL(amount, 0) + #{amount},
    available_amount = IFNULL(available_amount, 0) + #{amount}
WHERE line_id = #{lineId}
  AND IFNULL(amount, 0) + #{amount} >= 0
  AND IFNULL(available_amount, 0) + #{amount} >= 0
